def test_extract_nuxt_hydration_holdings_resolves_only_the_requested_component():
    payload = [
        None,
        "bldximpax-bldx-HoldingsComponent-1",
        "07/17/2026",
        [5],
        {
            "componentId": 1,
            "date": 2,
            "finData": 3,
        },
        {
            "ticker": 6,
            "description": 7,
            "quantity": 8,
            "market_value": 9,
            "percent_of_nav": 10,
            "figi": 11,
        },
        "AWK",
        "American Water Works Company, Inc.",
        "18460",
        "2574018.6",
        "0.0482",
        "BBG000BXDZV4",
        {
            "componentId": "unrelated-HoldingsComponent-1",
            "date": "01/01/2026",
            "finData": [],
        },
    ]
    raw_html = (
        '<script type="application/json" id="__NUXT_DATA__">' f"{json.dumps(payload)}" "</script>"
    )

    rows, composition_date = _extract_nuxt_hydration_holdings(
        raw_html,
        component_id="bldximpax-bldx-HoldingsComponent-1",
    )

    assert composition_date == date(2026, 7, 17)
    assert rows == [
        {
            "ticker": "AWK",
            "description": "American Water Works Company, Inc.",
            "quantity": "18460",
            "market_value": "2574018.6",
            "percent_of_nav": "0.0482",
            "figi": "BBG000BXDZV4",
        }
    ]


def _xlsx_workbook(rows: list[list[str]]) -> bytes:
    return _xlsx_workbook_sheets([rows])


def _xlsx_workbook_sheets(sheets: list[list[list[str]]]) -> bytes:
    def cell_ref(column_index: int, row_index: int) -> str:
        column = ""
        value = column_index + 1
        while value:
            value, remainder = divmod(value - 1, 26)
            column = chr(ord("A") + remainder) + column
        return f"{column}{row_index}"

    output = BytesIO()
    with zipfile.ZipFile(output, mode="w") as workbook:
        for sheet_index, rows in enumerate(sheets, start=1):
            sheet_rows = []
            for row_index, row in enumerate(rows, start=1):
                cells = []
                for column_index, value in enumerate(row):
                    cells.append(
                        f'<c r="{cell_ref(column_index, row_index)}" t="inlineStr">'
                        f"<is><t>{escape(value)}</t></is></c>"
                    )
                sheet_rows.append(f'<row r="{row_index}">{"".join(cells)}</row>')
            worksheet = (
                '<?xml version="1.0" encoding="UTF-8"?>'
                '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
                f'<sheetData>{"".join(sheet_rows)}</sheetData>'
                "</worksheet>"
            )
            workbook.writestr(f"xl/worksheets/sheet{sheet_index}.xml", worksheet)
    return output.getvalue()


class FakeResponse:
    def __init__(
        self,
        *,
        text: str = "",
        content: bytes | None = None,
        content_type: str = "text/csv",
        status_code: int = 200,
        url: str = "https://issuer.example/holdings.csv",
    ):
        self.text = text
        self.content = content if content is not None else text.encode()
        self.headers = {"content-type": content_type}
        self.status_code = status_code
        self.url = url

    def raise_for_status(self):
        return None

    def json(self):
        import json

        return json.loads(self.text)


class FakeAsyncClient:
    queue: list[FakeResponse | BaseException] = []
    requested: list[tuple[str, dict]] = []

    def __init__(self, *args, **kwargs):
        self.args = args
        self.kwargs = kwargs

    async def __aenter__(self):
        return self

    async def __aexit__(self, *args):
        return None

    async def get(self, url, **kwargs):
        type(self).requested.append((url, kwargs))
        if not type(self).queue:
            raise AssertionError(f"Unexpected URL {url}")
        response = type(self).queue.pop(0)
        if isinstance(response, BaseException):
            raise response
        return response

    async def post(self, url, **kwargs):
        type(self).requested.append((url, kwargs))
        if not type(self).queue:
            raise AssertionError(f"Unexpected URL {url}")
        response = type(self).queue.pop(0)
        if isinstance(response, BaseException):
            raise response
        return response


def test_water_island_parser_preserves_periodic_long_and_short_positions():
    adapter = get_holdings_adapter("water_island")
    assert adapter is not None

    rows, composition_date = adapter._parse_holdings_text(
        """
        AltShares Merger Arbitrage ETF Portfolio of Investments February 28, 2026 (unaudited)
        COMMON STOCKS - 98.07% Advertising - 1.01% Clear Channel Outdoor Holdings, Inc.(a)   434,198  $ 1,042,075
        Money Market Funds Morgan Stanley Institutional Liquidity Fund - Government Portfolio   886,309  $ 886,309
        NET ASSETS - 100.00%          $ 103,389,496
        SCHEDULE OF SECURITIES SOLD SHORT
        Allegiant Travel Co.   (11,873) $ (1,212,827)
        """,
        fund_name="AltShares Merger Arbitrage ETF",
    )

    assert composition_date == date(2026, 2, 28)
    assert [row.name for row in rows] == [
        "Clear Channel Outdoor Holdings, Inc.",
        "Morgan Stanley Institutional Liquidity Fund - Government Portfolio",
        "Allegiant Travel Co.",
    ]
    assert rows[0].weight == Decimal("1042075") / Decimal("103389496")
    assert rows[1].row_type == "cash"
    assert rows[2].shares == Decimal("-11873")
    assert rows[2].extra_data["position_side"] == "short"


