def test_every_registered_adapter_has_a_real_support_route():
    catalog = holdings_adapter_catalog()

    assert catalog
    for item in catalog:
        assert item["support_route_types"], item["adapter_key"]
        assert item["supports_sec_filing_fallback"] is True


def test_every_live_backed_adapter_owns_its_fetch_entry_point():
    """Prevent a live-backed issuer from silently inheriting another issuer's route."""
    for adapter_key, config in ISSUER_ADAPTER_CONFIGS.items():
        if not config.live_tested_default_route:
            continue
        adapter = get_holdings_adapter(adapter_key)
        assert adapter is not None, adapter_key
        assert "fetch_latest" in type(adapter).__dict__, adapter_key


def test_every_recognition_only_adapter_has_an_explicit_source_audit():
    fallback_only = {
        adapter_key
        for adapter_key, config in ISSUER_ADAPTER_CONFIGS.items()
        if not config.live_tested_default_route
    }

    assert set(FALLBACK_ISSUER_AUDITS) == fallback_only
    for adapter_key, audit in FALLBACK_ISSUER_AUDITS.items():
        assert audit.status
        assert audit.reason
        assert audit.next_action
        assert audit.last_checked <= date.today(), adapter_key


def test_every_registered_adapter_has_an_explicit_class():
    generated = []
    for adapter_key in registered_adapter_keys():
        adapter = get_holdings_adapter(adapter_key)
        assert adapter is not None
        if type(adapter).__name__.endswith("RecognitionOnlyHoldingsAdapter"):
            generated.append(adapter_key)

    assert generated == []


def test_etf_com_brand_reconciliation_batch_is_registered_and_audited():
    expected = set(ETF_COM_BRAND_RECONCILIATION_ISSUER_HINTS)
    native = set(ETF_COM_BRAND_RECONCILIATION_NATIVE_ADAPTERS)
    fallback_expected = expected - native

    assert expected
    assert native.issubset(expected)
    assert expected.issubset(set(registered_adapter_keys()))
    assert fallback_expected.issubset(set(FALLBACK_ISSUER_AUDITS))
    for adapter_key in fallback_expected:
        audit = FALLBACK_ISSUER_AUDITS[adapter_key]
        assert audit.status == "needs_first_party_route_discovery"
        adapter = get_holdings_adapter(adapter_key)
        assert adapter is not None
        assert type(adapter).__name__.endswith("ReconciledFallbackHoldingsAdapter")
    for adapter_key in native:
        assert adapter_key not in FALLBACK_ISSUER_AUDITS
        assert ISSUER_ADAPTER_CONFIGS[adapter_key].live_tested_default_route is True
        adapter = get_holdings_adapter(adapter_key)
        assert adapter is not None
        assert not type(adapter).__name__.endswith("ReconciledFallbackHoldingsAdapter")


